check "StorageClass local-retain: local-path provisioner, Retain, WaitForFirstConsumer" bash -c "[ \"\$(kubectl --context main get sc local-retain -o jsonpath='{.provisioner} {.reclaimPolicy} {.volumeBindingMode}')\" = 'rancher.io/local-path Retain WaitForFirstConsumer' ]"
check "local-retain is the only default StorageClass" bash -c "[ \"\$(kubectl --context main get sc -o jsonpath='{range .items[?(@.metadata.annotations.storageclass\.kubernetes\.io/is-default-class==\"true\")]}{.metadata.name} {end}')\" = 'local-retain ' ]"
check "PVC scratch got local-retain by default and is Bound" bash -c "[ \"\$(kubectl --context main -n lab-sc get pvc scratch -o jsonpath='{.status.phase} {.spec.storageClassName} {.spec.resources.requests.storage}')\" = 'Bound local-retain 200Mi' ]"
check "pod scratch-writer is Running and its volume's PV is retained" bash -c "pod_ready main scratch-writer lab-sc && pv=\$(kubectl --context main -n lab-sc get pvc scratch -o jsonpath='{.spec.volumeName}') && [ \"\$(kubectl --context main get pv \$pv -o jsonpath='{.spec.persistentVolumeReclaimPolicy}')\" = Retain ]"
